package org.joda.time.field;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.joda.time.DurationField;
import org.joda.time.DurationFieldType;
import org.joda.time.field.DurationField;
import org.joda.time.field.DurationFieldType;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UnsupportedDurationField_compareTo_TriageGen1Test {

    @Mock
    private DurationField mockDurationField;

    @Test
    public void testCompareTo_WhenDurationFieldIsSupported_ReturnsOne() {
        // Arrange
        UnsupportedDurationField unsupportedField = UnsupportedDurationField.getInstance(DurationFieldType.millis());
        when(mockDurationField.isSupported()).thenReturn(true);

        // Act
        int result = unsupportedField.compareTo(mockDurationField);

        // Assert
        assertEquals("Should return 1 when the passed field is supported", 1, result);
    }

    @Test
    public void testCompareTo_WhenDurationFieldIsNotSupported_ReturnsZero() {
        // Arrange
        UnsupportedDurationField unsupportedField = UnsupportedDurationField.getInstance(DurationFieldType.millis());
        when(mockDurationField.isSupported()).thenReturn(false);

        // Act
        int result = unsupportedField.compareTo(mockDurationField);

        // Assert
        assertEquals("Should return 0 when the passed field is not supported", 0, result);
    }
}
